"""Generated by testgen-agent for operation 'signup'.

Every test here was run against the live API and passed 3 times in a row before
being written. Review before committing: passing is not the same as correct."""

from conftest import fill, get_path  # noqa: F401


def test_valid_signup(client):
    r = client.request('POST', '/api/signup', json=fill({'name': 'Ada', 'email': '{{unique_email}}', 'password': 'correcthorse', 'confirm': 'correcthorse', 'age': 30}))
    assert r.status_code == 201, r.text
    body = r.json()
    assert get_path(body, 'name') == 'Ada'


def test_invalid_email_rejected(client):
    r = client.request('POST', '/api/signup', json=fill({'name': 'Ada', 'email': 'a@b', 'password': 'correcthorse', 'confirm': 'correcthorse', 'age': 30}))
    assert r.status_code == 400, r.text


def test_underage_rejected(client):
    r = client.request('POST', '/api/signup', json=fill({'name': 'Kid', 'email': '{{unique_email}}', 'password': 'correcthorse', 'confirm': 'correcthorse', 'age': 12}))
    assert r.status_code == 400, r.text


def test_missing_fields_rejected(client):
    r = client.request('POST', '/api/signup', json=fill({'email': '{{unique_email}}'}))
    assert r.status_code == 400, r.text
